let loaded=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fixed=(n,k=4)=>Number(n).toFixed(k), pct=n=>(n*100).toFixed(2)+'%';
export async function loadMl(){if(loaded)return;try{
const response=await fetch('ml/results/results.json');if(!response.ok)throw Error('Results could not be loaded.');const r=await response.json();loaded=true;
const rb=r.regression.find(x=>x.algorithm===r.regression_selected),cb=r.classification.find(x=>x.algorithm===r.classification_selected),tb=[...r.classification].sort((a,b)=>b.test_accuracy-a.test_accuracy)[0],kb=r.clustering.find(x=>x.algorithm===r.clustering_selected);
const card=(title,value,desc)=>`<article><span>${title}</span><strong>${value}</strong><small>${desc}</small></article>`;
const label=(name,selected,leader)=>`${esc(name)}${name===selected?'<em class="ml-badge">CV selected</em>':''}${name===leader&&leader!==selected?'<em class="ml-badge amber">Test leader</em>':''}`;
const table=(headers,body)=>`<div class="table-wrap"><table class="ml-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
document.getElementById('ml-content').innerHTML=`<div class="metrics ml-metrics">${card('Lowest insurance test RMSE',fixed(rb.test_rmse,2),'Histogram Gradient Boosting')}${card('Highest classification test accuracy',pct(tb.test_accuracy),'Random Forest · 78 of 80 correct')}${card('Highest clustering silhouette',fixed(kb.silhouette),'K Means · 5 clusters')}</div>
<section class="panel ml-overview"><h2>Different tasks need different metrics</h2><p>RMSE is lower-is-better prediction error. Accuracy measures correct class predictions. Silhouette measures cluster separation and is <b>not accuracy</b>. These scores should not be compared across tasks.</p><p>Supervised models are selected by training cross-validation. The held-out test is evaluated afterwards. K Nearest Neighbors was the CV-selected classifier (${pct(cb.cv_accuracy)} CV; ${pct(cb.test_accuracy)} test); Random Forest has the highest observed test accuracy (${pct(tb.test_accuracy)}).</p></section>
<div class="ml-tabs" role="tablist" aria-label="Machine learning task"><button role="tab" aria-selected="true" data-ml="regression">01 &nbsp; Boosting</button><button role="tab" aria-selected="false" data-ml="classification">02 &nbsp; Classification</button><button role="tab" aria-selected="false" data-ml="clustering">03 &nbsp; Clustering</button></div>
<section class="panel ml-task" id="ml-regression"><div class="panel-title"><div><h2>Predict insurance charges</h2><p class="muted">insurance_pre.csv · 1,338 original rows · one exact duplicate removed</p></div><a class="secondary" href="ml/results/regression_results.csv" download>Results CSV ↓</a></div><p>Training: 1,069 rows. Held-out test: 268 rows. All five predictors are used; imputation, scaling and category encoding are fitted inside each training fold.</p>${table(['Algorithm','CV RMSE ↓','CV std','Test RMSE ↓','Test MAE ↓','Test R² ↑'],[...r.regression].sort((a,b)=>a.cv_rmse-b.cv_rmse).map(x=>`<tr><td>${label(x.algorithm,r.regression_selected)}</td><td>${fixed(x.cv_rmse,2)}</td><td>${fixed(x.cv_std,2)}</td><td>${fixed(x.test_rmse,2)}</td><td>${fixed(x.test_mae,2)}</td><td>${fixed(x.test_r2)}</td></tr>`).join(''))}<div class="ml-chart-row"><img src="ml/results/insurance_predictions.png" alt="Actual versus predicted insurance charges for the CV-selected model"><div><h3>What this result means</h3><p>Histogram Gradient Boosting has the lowest cross-validation RMSE and the lowest test RMSE among these three candidates. Its test R² is ${fixed(rb.test_r2)}. This is a regression score, not “90% accuracy”.</p><p>Errors use the dataset’s original charge units; no currency is assumed. The small difference from Gradient Boosting is not evidence of a reliably superior model on every split.</p><a href="ml/results/insurance_selected_model.joblib" download>Download selected trained model ↓</a></div></div></section>
<section class="panel ml-task" id="ml-classification" hidden><div class="panel-title"><div><h2>Predict ad purchase outcomes</h2><p class="muted">Social_Network_Ads.csv · 400 rows · Purchased is the target</p></div><a class="secondary" href="ml/results/classification_results.csv" download>Results CSV ↓</a></div><p>Training: 320 rows. Held-out test: 80 rows. User ID is excluded. Identical Gender/Age/Salary combinations stay together across splits and CV folds to avoid overlap.</p>${table(['Algorithm','CV accuracy ↑','CV std','Test accuracy ↑','Precision','Recall','F1','ROC AUC'],[...r.classification].sort((a,b)=>b.cv_accuracy-a.cv_accuracy).map(x=>`<tr><td>${label(x.algorithm,r.classification_selected,tb.algorithm)}</td><td>${pct(x.cv_accuracy)}</td><td>${pct(x.cv_std)}</td><td>${pct(x.test_accuracy)}</td><td>${fixed(x.test_precision)}</td><td>${fixed(x.test_recall)}</td><td>${fixed(x.test_f1)}</td><td>${fixed(x.test_roc_auc)}</td></tr>`).join(''))}<div class="ml-chart-row"><img src="ml/results/ads_confusion_matrix.png" alt="Held-out confusion matrix of the CV-selected K Nearest Neighbors model"><div><h3>Selection versus observed test performance</h3><p>K Nearest Neighbors has the best training CV accuracy. Its reserved test predicts 77 of 80 records correctly. Random Forest predicts 78 of 80 correctly, but the test set is not used to choose the model.</p><p>The difference is one test record. These small-sample results do not establish a universal winner. Precision, recall and F1 use Purchased = 1 as the positive class.</p><a href="ml/results/ads_selected_model.joblib" download>Download CV-selected trained model ↓</a></div></div></section>
<section class="panel ml-task" id="ml-clustering" hidden><div class="panel-title"><div><h2>Segment mall customers</h2><p class="muted">Mall_Customers.csv · 200 customers · no target labels</p></div><a class="secondary" href="ml/results/clustering_results.csv" download>Results CSV ↓</a></div><p>Annual Income and Spending Score are standardized. Every algorithm evaluates 2–8 clusters on the same data. CustomerID, Genre and Age are excluded from this two-feature segmentation.</p>${table(['Algorithm','Selected k','Silhouette ↑','Davies–Bouldin ↓','Calinski–Harabasz ↑'],[...r.clustering].sort((a,b)=>b.silhouette-a.silhouette).map(x=>`<tr><td>${esc(x.algorithm)}${x.algorithm===r.clustering_selected?'<em class="ml-badge">Best silhouette</em>':''}</td><td>${x.clusters}</td><td>${fixed(x.silhouette)}</td><td>${fixed(x.davies_bouldin)}</td><td>${fixed(x.calinski_harabasz,2)}</td></tr>`).join(''))}<div class="ml-chart-row"><img src="ml/results/mall_clusters.png" alt="Five K Means customer clusters plotted by annual income and spending score"><div><h3>Five segments in this feature space</h3><p>K Means gives the highest silhouette, ${fixed(kb.silhouette)}, with five clusters. Ward and Gaussian Mixture produce similar scores. Cluster numbers are arbitrary identifiers.</p><p>This score is computed on the same sample used to select k. It describes internal structure and does not measure held-out accuracy or establish meaningful business categories.</p><a href="ml/results/mall_cluster_assignments.csv" download>Download customer cluster assignments ↓</a><br><a href="ml/results/cluster_all_candidates.csv" download>All 21 cluster candidates ↓</a></div></div></section>
<section class="panel ml-downloads"><div><h2>Data, code and evidence</h2><p class="muted">Original CSVs are included unchanged. Every displayed score comes from the saved training run.</p></div><div class="download-grid"><a href="ml/data/insurance_pre.csv" download>Insurance dataset ↓</a><a href="ml/data/Social_Network_Ads.csv" download>Advertising dataset ↓</a><a href="ml/data/Mall_Customers.csv" download>Mall dataset ↓</a><a href="ml/train_compare.py" download>Complete training code ↓</a><a href="ml/requirements.txt" download>Python requirements ↓</a><a href="ml/README.md" download>Method and results report ↓</a><a href="ml/results/results.json" download>All results and parameters ↓</a><a href="ml/results/regression_predictions.csv" download>Insurance test predictions ↓</a><a href="ml/results/classification_predictions.csv" download>Classification test predictions ↓</a></div><p class="muted">Run <code>python ml/train_compare.py</code> locally with the matching folder structure. Training ran with scikit-learn ${esc(r.environment.scikit_learn)} and seed ${r.seed}. Model files use joblib; load only files you trust.</p></section>
<section class="panel ml-overview"><h2>How to interpret these comparisons</h2><p>The supervised algorithms use five-fold training CV and one reserved outer test split. Hyperparameter tuning and model-family selection reuse the CV scores, so those scores have selection bias. A different split may change the ranking. CV standard deviations are not confidence intervals.</p><p>Clustering is exploratory: all customers are used to fit and score each candidate. The website displays saved results and does not retrain models in your browser.</p></section>`;
document.querySelectorAll('[data-ml]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-ml]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('.ml-task').forEach(s=>s.hidden=s.id!=='ml-'+b.dataset.ml);});
}catch(e){document.getElementById('ml-content').textContent=e.message;}}
